const raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json.content ??
  "";

if (!raw) {
  throw new Error("No AI response was found.");
}

const aiText = String(raw).trim();

// OCR text
const ocrText =
  $('HTTP Request').first().json.ParsedResults?.[0]?.ParsedText ?? "";

const combinedText = `${aiText}\n${ocrText}`.toLowerCase();

//
// 1. Try to read structured fields if the AI provides them
//

const riskMatch = aiText.match(
  /(?:Risk[_\s-]*Level|Risk)\s*[:\-]\s*(High|Medium|Low|Safe)/i
);

const scamMatch = aiText.match(
  /(?:Scam[_\s-]*Type|Scam Type|Type)\s*[:\-]\s*([^\n]+)/i
);

const confidenceMatch = aiText.match(
  /(?:Confidence[_\s-]*Score|Confidence)\s*[:\-]\s*(\d+(?:\.\d+)?)/i
);

//
// 2. Determine scam type
//

let scamType = scamMatch?.[1]?.trim() ?? "";

if (!scamType) {
  if (
    /phishing|phishing attempt|credential theft|fake login|sign in.*account|verify.*account/i.test(
      combinedText
    )
  ) {
    scamType = "Phishing";
  } else if (
    /otp|one[- ]time password/i.test(combinedText)
  ) {
    scamType = "OTP Scam";
  } else if (
    /payment|money transfer|bank transfer|fee/i.test(combinedText)
  ) {
    scamType = "Payment Scam";
  } else if (
    /fake job|job offer|recruitment scam/i.test(combinedText)
  ) {
    scamType = "Fake Job";
  } else if (
    /impersonat|pretending to be/i.test(combinedText)
  ) {
    scamType = "Impersonation";
  } else if (
    /login|sign in|password|credential/i.test(combinedText)
  ) {
    scamType = "Fake Login";
  } else {
    scamType = "None";
  }
}

//
// 3. Determine risk level
//

let riskLevel = riskMatch?.[1] ?? "";

if (!riskLevel) {
  let strongIndicators = 0;

  if (/phishing|phishing attempt|credential theft/i.test(combinedText)) {
    strongIndicators++;
  }

  if (/sign in|login|validate your account|verify your account/i.test(combinedText)) {
    strongIndicators++;
  }

  if (/password|credential|username|account/i.test(combinedText)) {
    strongIndicators++;
  }

  if (/click|link|http|https|www\./i.test(combinedText)) {
    strongIndicators++;
  }

  if (/urgent|immediately|action required|verification/i.test(combinedText)) {
    strongIndicators++;
  }

  if (/microsoft|office 365/i.test(combinedText)) {
    strongIndicators++;
  }

  if (strongIndicators >= 4) {
    riskLevel = "High";
  } else if (strongIndicators >= 2) {
    riskLevel = "Medium";
  } else if (strongIndicators === 1) {
    riskLevel = "Low";
  } else {
    riskLevel = "Safe";
  }
}

//
// 4. Determine confidence score
//

let confidenceScore = confidenceMatch
  ? Number(confidenceMatch[1])
  : 0;

// If AI didn't give a useful score, calculate an evidence score
if (
  !Number.isFinite(confidenceScore) ||
  confidenceScore <= 0
) {
  let score = 0;

  if (/phishing|phishing attempt|credential theft/i.test(combinedText)) {
    score += 25;
  }

  if (/sign in|login|validate your account|verify your account/i.test(combinedText)) {
    score += 20;
  }

  if (/password|credential|username|account/i.test(combinedText)) {
    score += 20;
  }

  if (/click|link|http|https|www\./i.test(combinedText)) {
    score += 15;
  }

  if (/urgent|immediately|action required|verification/i.test(combinedText)) {
    score += 10;
  }

  if (/microsoft|office 365/i.test(combinedText)) {
    score += 10;
  }

  confidenceScore = Math.min(score, 95);
}

// Keep score between 0 and 100
confidenceScore = Math.max(
  0,
  Math.min(Number(confidenceScore), 100)
);

//
// 5. Explanation
//

const explanation =
  aiText ||
  "No explanation was returned by the AI.";

//
// 6. Safety recommendation
//

const safetyRecommendations =
  "Do not click suspicious links or provide passwords, OTPs, or other sensitive information. Verify the message through the official organization.";

//
// 7. Return structured data
//

return {
  json: {
    risk_level: riskLevel,
    scam_type: scamType,
    confidence_score: confidenceScore,
    explanation: explanation,
    safety_recommendations: safetyRecommendations,
    ocr_text: ocrText
  }
};
